  const nb=v=>/^\d+(\.\d+)?$/.test(lkT(v))?+lkT(v):null,r1=x=>String(Math.round(x*10)/10),tpn=nb(p.tpN),epn=nb(p.epN),ten=nb(p.teN),pr=[];
